package com.kitchenos.connect.ui;
/** Native presentation copied from the reviewed 22 October catalogue; no motor programs. */
public final class FunctionPageContent {
 public static final class Data {public final String title,tool,tip,program;public final String[][] steps;Data(String title,String tool,String tip,String[][] steps,String program){this.title=title;this.tool=tool;this.tip=tip;this.steps=steps;this.program=program;}}
 public static Data get(String id){switch(id){
case "manual":return new Data("Manuell kochen","blade","Mehr Zeit verändert den Gargrad; eine höhere Messerstufe die Feinheit. Heizung nur bei Bedarf wählen.",new String[][]{{"Vorbereiten","Passendes Werkzeug bei Stillstand einsetzen. Zutaten einfüllen und die Füllmarkierung beachten."},{"Nach Rezept arbeiten","Zeit, Temperatur und Bewegung passend zur Zubereitung wählen."},{"Ergebnis prüfen","Konsistenz und Garzustand prüfen. Vor dem Öffnen den Messerstillstand abwarten."}},"");
case "lidless":return new Data("Ohne Deckel kochen","cover","Zum Reduzieren mehr Zeit wählen. Bis 100 °C. Ohne Bewegung: fest 0. Sanft rühren: rückwärts 0,5–1.",new String[][]{{"Mit Flüssigkeit beginnen","Messerabdeckung einsetzen. Sauce mit ausreichend Flüssigkeit einfüllen."},{"Beim Köcheln dabeibleiben","Beim offenen Kochen verdampft mehr Flüssigkeit. Die Saucendicke regelmäßig prüfen."},{"Vor Zugaben stoppen","Stillstand abwarten. Hände und Spatel während der Bewegung aus dem Topf halten."}},"");
case "scale":return new Data("Waage","blade","Tara setzt die Anzeige für die nächste Zutat auf null. Zubehör möglichst vorher einsetzen.",new String[][]{{"Ruhig aufstellen","Mixtopf und Zubehör einsetzen. Die Maschine auf eine feste, ebene Fläche stellen."},{"Zutat für Zutat wiegen","Vor einer neuen Zutat Tara wählen. Langsam zugeben, ohne die Maschine zu berühren."},{"Anzeige abwarten","Erst den stabilen Wert ablesen. Gesamtlast und Füllmarkierung beachten."}},"");
case "eggs":return new Data("Eier kochen","basket","Gargrad oder eigene Zeit wählen, Zeit bei Bedarf anpassen und bewusst starten. Garzeit ab erreichtem 100-°C-Topfsensorwert; Aufheizen davor. Messer fest 0.",new String[][]{{"Im Dampf garen","250 ml Wasser für den vorgesehenen Versuch einfüllen. Eier immer im Gareinsatz über dem Wasser dampfgaren. Diese Wassermenge und die Garzeiten sind noch zu erproben; den Versuch beobachten und Restwasser prüfen."},{"Eier hineinlegen","Unbeschädigte Eier vorsichtig in den Einsatz legen. Größe und Ausgangstemperatur beachten."},{"Nach dem Garen entnehmen","Gargrad prüfen und Eier mit einem geeigneten Hilfsmittel herausnehmen."}},"");
case "water":return new Data("Wasser erhitzen","blade","Die Zieltemperatur passend zur Verwendung wählen. Mehr oder kälteres Wasser braucht mehr Zeit.",new String[][]{{"Trinkwasser einfüllen","Mindestmenge und Füllmarkierung aus der Geräteanleitung beachten."},{"Nur klares Wasser erhitzen","Milch, Suppen und Saucen gehören zur Funktion Erwärmen."},{"Vorsichtig ausgießen","Beim Öffnen Abstand zu heißem Dampf halten."}},"");
case "rice":return new Data("Reis kochen","basket","Die Reissorte antippen oder per Drehknopfdruck bestätigen; die Wahl startet unmittelbar. 25/40 Minuten sind noch nicht am Gerät kalibrierte Richtwerte einschließlich Aufheizen.",new String[][]{{"Reis vorbereiten","Nach Packungsangabe waschen, in den Gareinsatz geben und den Einsatz korrekt einhängen."},{"Wasser passend dosieren","Ein Geräte-Rezept für Sorte und Menge verwenden. Das 1:2-Verhältnis des Quellverfahrens im Topf gilt hier nicht automatisch."},{"Körner prüfen","Nach dem Garen die Konsistenz prüfen. Den heißen Einsatz mit dem vorgesehenen Hilfsmittel entnehmen."}},"");
case "dough":return new Data("Teig kneten","blade","Dauer nach Teigart und Mehlmenge wählen. Das Programm übernimmt Bewegung und Pausen; Heizung aus.",new String[][]{{"Zutaten einfüllen","Die Reihenfolge und erlaubte Menge eines passenden Geräte-Rezepts einhalten."},{"Teigart beachten","Schwere Brot- und Pizzateige brauchen andere Abläufe als weiche Teige."},{"Teigstruktur prüfen","Nach dem Kneten prüfen, ob der Teig gleichmäßig ist und zum Rezept passt."}},"Stufe 3, Heizung aus: 2 s kneten / 2 s Pause → 3 s kneten / 3 s Pause → 4 s kneten / 2 s Pause. Wiederholt bis zum Zeitende; Richtung nach jeder Pause wechseln.");
case "steam":return new Data("Dampfgaren","steam","Größere Stücke brauchen mehr Zeit. Die Garphase beginnt mit dem Dampf; das Messer bleibt stehen.",new String[][]{{"Wasser und Gemüse vorbereiten","Wasser nach Geräte-Rezept einfüllen. Gemüse in ähnlich große Stücke schneiden."},{"Aufsatz richtig füllen","Zutaten locker verteilen, Dampföffnungen freihalten und den Deckel schließen."},{"Bissfestigkeit prüfen","Nach dem Garen den heißen Deckel vom Körper weg öffnen."}},"");
case "chop":return new Data("Zerkleinern","blade","Kurz beginnen: weniger Zeit ergibt gröbere Stücke. Für feinere Ergebnisse kurz nacharbeiten.",new String[][]{{"Zutaten vorbereiten","Zwiebeln schälen und vierteln; anderes Gemüse in ähnlich große Stücke teilen."},{"Ohne Aufsatz zerkleinern","Nur das Messer verwenden und den Deckel schließen. Heiße Zutaten vorher abkühlen lassen."},{"Bei Stillstand nachschieben","Feinheit prüfen und Zutaten bei Bedarf mit dem Spatel nach unten schieben."}},"");
case "mix":return new Data("Mixen","blade","Niedriger mischen für gröbere Ergebnisse, kurz höher für feinere. Hohe Stufen nur unter 60 °C.",new String[][]{{"Mit Flüssigkeit einfüllen","Obst in Stücke schneiden und mit Flüssigkeit in den Mixtopf geben. Platz für Schaum lassen."},{"Aufsätze entfernen","Für hohe Stufen nur das Messer verwenden und den Deckel schließen."},{"Konsistenz prüfen","Bei Stillstand prüfen und bei Bedarf Flüssigkeit ergänzen."}},"");
case "puree":return new Data("Pürieren","blade","Feinheit wählen und kurz beginnen. Bei Bedarf Zeit verlängern; die Heizung bleibt ausgeschaltet.",new String[][]{{"Weich garen","Gemüse zuerst weich garen und ausreichend Flüssigkeit zugeben."},{"Vor hohen Stufen abkühlen","Topf und Inhalt auf unter 60 °C abkühlen lassen. Rühraufsatz entfernen und Deckel schließen."},{"Cremigkeit prüfen","Bei Stillstand prüfen. Für ein dünneres Püree Flüssigkeit ergänzen."}},"");
case "stir":return new Data("Rühren","cover","Sanft für empfindliche Stücke, normal zum Vermengen. Pausen sind optional; mit Abdeckung bis 100 °C.",new String[][]{{"Messerabdeckung einsetzen","Bei Stillstand sicher auf das Messer setzen. Die Grafik bestätigt nicht den tatsächlichen Sitz."},{"Mit Flüssigkeit rühren","Ausreichend Flüssigkeit zugeben und nicht trocken erhitzen."},{"Werkzeug passend wählen","Ohne Abdeckung manuell rückwärts rühren. Für Aufschlagen den Schneebesen verwenden."}},"");
case "whip":return new Data("Schlagen","whisk","Mit kurzer Zeit beginnen und früh kontrollieren. Menge und Fettgehalt beeinflussen die nötige Dauer.",new String[][]{{"Schneebesen aufsetzen","Bei Stillstand sicher auf das Messer setzen und den Deckel schließen."},{"Zutaten passend vorbereiten","Sahne gut kühlen. Für Eiweiß müssen Topf und Schneebesen sauber und fettfrei sein."},{"Festigkeit beobachten","Rechtzeitig stoppen. Zu langes Schlagen kann Sahne trennen; Aufsatz erst bei Stillstand abnehmen."}},"");
case "emulsify":return new Data("Emulgieren","blade","Dauer an Menge und langsame Ölzugabe anpassen. Dieses Profil ist für kalte Emulsionen gedacht.",new String[][]{{"Basis vorbereiten","Grundzutaten nach Rezept in den Mixtopf geben. Das Profil verwendet das Messer ohne Heizung."},{"Öl langsam zugeben","Öl über den vom Rezept vorgesehenen Deckelweg einlaufen lassen."},{"Emulsion prüfen","Bei Stillstand prüfen: Das Dressing soll gleichmäßig sein und keine Ölschicht bilden."}},"");
case "thicken":return new Data("Andicken","blade","Ei: 80 °C und 10 Minuten. Mehl oder Stärke: 100 °C und 12 Minuten. Die Zeit und Messerbewegung sind fest; die Bindung wird nicht erkannt.",new String[][]{{"Bindemittel wählen","Für eihaltige Saucen wie Hollandaise, Béarnaise oder Vanillesoße 80 °C wählen; mit Mehl oder Stärke 100 °C."},{"Zutaten vorbereiten","Zutaten nach Rezept einfüllen. Stärke mit etwas kalter Rezeptflüssigkeit glatt rühren. Empfindliche Stücke vorher herausnehmen."},{"Konsistenz prüfen","Nach dem Lauf bei Messerstillstand prüfen. Die Konsistenz hängt von Zutaten und Mengen ab; Cremes können beim Abkühlen nachdicken."}},"");
case "turbo":return new Data("Turbo","blade","1 oder 2 Sekunden und Stufe 10, 11 oder 12 wählen. Mit einem kurzen Impuls beginnen und das Ergebnis prüfen.",new String[][]{{"Nur geeignete kalte Zutaten","Menge nach Geräte-Rezept wählen. Der Topf muss unter 60 °C liegen."},{"Aufsätze entfernen","Messerabdeckung und Schneebesen entfernen. Deckel und Messbecher schließen."},{"Nach jedem Impuls prüfen","Stillstand abwarten und nur bei Bedarf einen weiteren kurzen Lauf wählen."}},"");
case "caramel":return new Data("Zucker karamellisieren","blade","Zeit und Temperatur aus einem geprüften Karamellrezept übernehmen. Freies Anbraten ersetzt es nicht.",new String[][]{{"Ein Geräte-Rezept verwenden","Zuckerart, Menge, Wasser und Temperaturverlauf müssen auf die Maschine abgestimmt sein."},{"Ohne Kunststoff-Zubehör","Messerabdeckung und Schneebesen entfernen. Dabeibleiben und die Bräunung beobachten."},{"Heißes Karamell beachten","Nach Rezept weiterverarbeiten und vor dem Probieren abkühlen lassen."}},"");
case "grind":return new Data("Mahlen","blade","Kurze Abschnitte wählen und das Ergebnis prüfen. Nüsse brauchen andere Zeiten als Getreide.",new String[][]{{"Trocken vorbereiten","Topf, Messer und Zutaten müssen trocken sein. Nur geeignete Zutaten und Mengen verwenden."},{"Ohne Aufsatz mahlen","Keinen Schneebesen und keine Messerabdeckung einsetzen."},{"Feinheit kontrollieren","Zwischen Läufen Stillstand abwarten. Ölhaltige Nüsse können bei zu langer Verarbeitung zu Mus werden."}},"2 × (5 s Stufe 8 / 2 s Pause) → 5 s Stufe 8 → 1 s Pause");
case "ice":return new Data("Eis zerkleinern","blade","Kurze Impulse mit Pausen verwenden. Für feinere Ergebnisse erst nach einer Kontrolle nacharbeiten.",new String[][]{{"Passende Eiswürfel verwenden","Nur laut Geräte-Rezept geeignete Würfelgrößen und Mengen einfüllen."},{"Nur das Messer verwenden","Aufsätze entfernen. Deckel und Messbecher schließen."},{"Stückgröße prüfen","Nach dem Stillstand prüfen, ob das Eis schon die gewünschte Feinheit hat."}},"5 × (2 s Stufe 6 / 3 s Pause)");
case "warm":return new Data("Erwärmen","blade","Zieltemperatur bis 90 °C und eine von drei Linkslauf-Stufen wählen. Der Lauf endet durch Stoppen, spätestens nach 120 Minuten.",new String[][]{{"Speise einfüllen","Bereits zubereitete Suppe oder Sauce mit ausreichend Flüssigkeit einfüllen. Klares Wasser separat erhitzen."},{"Sanft rückwärts rühren","Nur das Messer verwenden. Stufe 0,5, 1 oder 1,5 wählen; empfindliche Stücke mit 0,5 beginnen."},{"Wärme selbst prüfen","Die Zieltemperatur stoppt den Lauf nicht. Speise gleichmäßig erwärmen, selbst prüfen und Stoppen drücken. Die Topfanzeige misst nicht die Kerntemperatur."}},"");
case "fry":return new Data("Anbraten","blade","Zeit und Temperatur einstellen, dann den Rührrhythmus wählen und starten. Immer rückwärts auf Stufe 1. In den automatischen Messerpausen bleibt die Temperaturregelung aktiv. Stoppen beendet den gesamten Kochvorgang. Mit 140 °C beginnen, dabeibleiben und Bräunung prüfen. Maximal 180 °C und 30 Minuten; noch keine reale Kalibrierung der Intervalle.",new String[][]{{"Zutaten und Fett vorbereiten","Zwiebeln beispielsweise in Streifen schneiden. Geeignetes Öl oder Fett nach Rezept zugeben."},{"Kunststoff-Zubehör entfernen","Messerabdeckung, Schneebesen und Gareinsatz herausnehmen. Nicht leer erhitzen."},{"Bei der Maschine bleiben","In kleinen Portionen anbraten und die Bräunung beobachten. Vor einer Kontrolle stoppen."}},"");
case "slow":return new Data("Langsam garen","cover","1 bis 8 Stunden und 37 bis 98 °C wählen. Das Messer rührt in kurzen Phasen fest rückwärts auf 0,5.",new String[][]{{"Gericht vorbereiten","Fleisch bei Bedarf vorher anbraten. Zutaten mit ausreichend Sauce oder Garflüssigkeit bedecken; Füllmarkierung beachten."},{"Messerabdeckung einsetzen","Weiche Stücke bei Stillstand schützen und genügend Flüssigkeit im Topf halten. Deckel schließen."},{"Nach dem Garen prüfen","Garzustand und bei Fleisch die sichere Kerntemperatur nach Rezept prüfen. Der Sollwert am Topf zeigt keine Kerntemperatur."}},"5 s rückwärts 0,5 / 25 s Pause, wiederholt bis zum Zeitende");
case "sousvide":return new Data("Sous-vide","cover","Solltemperatur allein bestätigt keine gleichmäßige Badtemperatur. Nur ein geprüftes Profil wählen.",new String[][]{{"Beutel und Wasserbad vorbereiten","Geeignete hitzebeständige Beutel, Messerabdeckung und ausreichend Wasser verwenden."},{"Nach geprüftem Rezept garen","Zeit und Temperatur nach Lebensmittel und Dicke wählen. Vorheizen und Haltezeit trennen."},{"Wasserstand kontrollieren","Beutelposition und Wasserstand nach Rezept prüfen. Beutel vom Messer fernhalten."}},"");
case "ferment":return new Data("Fermentieren","blade","Temperatur und Reifezeit müssen zur Kultur passen. Zwei Stunden ersetzen kein Langzeitprogramm.",new String[][]{{"Sauber vorbereiten","Mit sauberen Gefäßen und einem konkreten Rezept für die gewählte Kultur arbeiten."},{"Zutaten in Reihenfolge zugeben","Milch, Kultur und Mengen nach Rezept vorbereiten. Während der Reifung bleibt das Messer stehen."},{"Danach kühlen","Das Ergebnis nach Rezept prüfen, kühlen und lagern."}},"");
case "clean":return new Data("Vorspülen","blade","Vorbereiten, Programm wählen und starten.",new String[][]{{"Wasser einfüllen","Grobe Reste und alle Aufsätze entfernen. 500 ml bis höchstens 1 l Wasser einfüllen."},{"Schließen und vorbereiten","Deckel und Messbecher einsetzen. Heiße Programme nur mit Wasser; für Kurz und Teig den Topf auf höchstens 80 °C abkühlen lassen."},{"Programm wählen","Auf der nächsten Seite stehen Dauer und Einsatzzweck. Antippen startet. Danach ausgießen und klar nachspülen."}},"");
default:throw new IllegalArgumentException(id);}}
 /** Two deliberate lines above the options; preparation stays on the first page. */
 public static String settingsTip(String id){switch(id){
 case "manual":return "Zeit, Temperatur und Stufe frei wählen.\nHeizung nur bei Bedarf einschalten.";
 case "scale":return "Gewicht oben ablesen.\nMit Tara die nächste Zutat einzeln wiegen.";
 case "stir":return "Bewegung wählen · mit Abdeckung bis 100 °C\nPausen schonen empfindliche Stücke.";
 case "water":return "Zieltemperatur wählen.\nMehr oder kälteres Wasser braucht mehr Zeit.";
 case "fry":return "Mit 140 °C beginnen und dabeibleiben.\nBräunung prüfen, bei Bedarf kurz verlängern.";
 case "whip":return "Zutat wählen und mit kurzer Zeit beginnen.\nFrüh prüfen, damit Sahne nicht zu Butter wird.";
 case "clean":return "Programm auf der Auswahlseite starten.\nDanach Wasser ausgießen und klar nachspülen.";
 case "mix":return "Kurz beginnen, dann die Feinheit prüfen.\nHohe Stufen nur bei Topftemperatur unter 60 °C.";
 case "emulsify":return "Öl langsam zugeben, Zeit an die Menge anpassen.\nFür kalte Emulsionen · Heizung bleibt aus.";
 case "warm":return "Bis 90 °C · Linkslauf 0,5 / 1 / 1,5.\nBei gewünschter Wärme selbst stoppen · max. 120 Min.";
 case "lidless":return "Bewegung wählen · höchstens 100 °C\nOhne Bewegung: fest 0 · Rühren: rückwärts 0,5–1";
 case "eggs":return "250 ml Wasser · Eier im Gareinsatz\nGarzeit ab 100 °C am Topfsensor, noch nicht kalibriert.";
 case "rice":return "Reissorte wählen · feste Laufzeit inkl. Aufheizen.\n25/40 Min Richtwerte; Garzustand danach prüfen.";
 case "dough":return "Teigart wählen, Dauer an die Menge anpassen.\nBewegung und Pausen laufen automatisch.";
 case "steam":return "Zeit an die Größe der Stücke anpassen.\nDie Garphase beginnt mit dem Dampf.";
 case "chop":return "Feinheit wählen und kurz beginnen.\nErgebnis prüfen, bei Bedarf kurz nacharbeiten.";
 case "puree":return "Zeit einstellen, dann Cremigkeit bestätigen und starten.\nGrob 6 · Cremig 8 · Fein 10 · sanfter Hochlauf.";
 case "grind":return "Kurze Abschnitte mit Pausen.\nFeinheit prüfen; Nüsse werden schnell zu Mus.";
 case "ice":return "Kurze Impulse mit Pausen.\nStückgröße vor einem weiteren Lauf prüfen.";
 case "slow":return "1–8 Std. · 37–98 °C · rückwärts 0,5 fest.\nSauce/Flüssigkeit nach Rezept · Garzustand prüfen.";
 case "sousvide":return "Nur ein geprüftes Wasserbadprofil verwenden.\nSolltemperatur allein bestätigt kein Garergebnis.";
 case "ferment":return "Temperatur und Zeit müssen zur Kultur passen.\nEin eigenes Langzeitprogramm ist nötig.";
 case "thicken":return "Ei: 80 °C · 10 Min.  |  Mehl/Stärke: 100 °C · 12 Min.\nMesserstufe 2 und Dauer sind fest · Konsistenz prüfen.";
 case "turbo":return "1–2 Sekunden · Stufe 10, 11 oder 12\nJeder Start löst genau einen Impuls aus.";
 case "caramel":return "Ein geprüftes Karamellrezept verwenden.\nFreies Anbraten ersetzt diesen Ablauf nicht.";
 default:throw new IllegalArgumentException(id);}}
 public static String tool(String id){switch(id){case "cover":return "Messerabdeckung";case "whisk":return "Schneebesen";case "basket":return "Gareinsatz";case "steam":return "Dampfgaraufsatz";default:return "";}}
 private FunctionPageContent(){}
}
